test_that("calc_excess produces expected non-bootstrapped output", {
  # Load and prepare test data
  data(example_qsip)
  
  # Filter out non-target lineages as shown in README
  tx <- unique(example_qsip[, c('asv_id', 'Kingdom', 'Phylum', 'Class', 'Order', 'Family', 'Genus')])
  unassign <- tx[Kingdom == 'Unassigned', asv_id]
  euk <- tx[Kingdom == 'Eukaryota', asv_id]
  arch <- tx[Kingdom == 'Archaea', asv_id]
  mito_chloro <- tx[, tax_string := paste(Phylum, Class, Order, Family, Genus, sep = ';')
                    ][grepl('mitochond|chloroplast', tax_string, ignore.case = T), asv_id]
  
  example_qsip_filtered <- example_qsip[!asv_id %in% c(arch, mito_chloro, euk, unassign)]
  
  # Relativize sequence abundances
  example_qsip_filtered[, rel_abund := seq_abund / sum(seq_abund), by = sampleID]
  
  # Calculate WADs first (required input for calc_excess)
  wads <- calc_wad(example_qsip_filtered,
                   tax_id = 'asv_id', sample_id = 'sampleID', frac_id = 'fraction',
                   frac_dens = 'Density.g.ml', frac_abund = 'avg_16S_g_soil',
                   rel_abund = 'rel_abund',
                   grouping_cols = c('treatment', 'isotope', 'iso_trt', 'Phylum'))
  
  # Test calc_excess non-bootstrapped
  eaf <- calc_excess(wads, tax_id = 'asv_id', sample_id = 'sampleID',
                     iso_trt = 'iso_trt', isotope = 'isotope')
  
  # Basic structure tests
  expect_s3_class(eaf, "data.table")
  expect_true(nrow(eaf) > 0)
  expect_true("eaf" %in% names(eaf))
  
  # Check that EAF values are numeric
  expect_true(is.numeric(eaf$eaf))
  
  # Check that we have the expected grouping columns
  expected_cols <- c('asv_id', 'treatment', 'isotope', 'iso_trt', 'Phylum', 'eaf')
  expect_true(all(expected_cols %in% names(eaf)))
  
  # Check that NA values are removed (as stated in documentation)
  expect_false(any(is.na(eaf$eaf)))
  
  # Check that we have both positive and potentially negative EAF values
  expect_true(length(unique(eaf$eaf)) > 1)
})

test_that("calc_excess produces expected bootstrapped output", {
  # Load and prepare test data
  data(example_qsip)
  
  # Filter out non-target lineages
  tx <- unique(example_qsip[, c('asv_id', 'Kingdom', 'Phylum', 'Class', 'Order', 'Family', 'Genus')])
  unassign <- tx[Kingdom == 'Unassigned', asv_id]
  euk <- tx[Kingdom == 'Eukaryota', asv_id]
  arch <- tx[Kingdom == 'Archaea', asv_id]
  mito_chloro <- tx[, tax_string := paste(Phylum, Class, Order, Family, Genus, sep = ';')
                    ][grepl('mitochond|chloroplast', tax_string, ignore.case = T), asv_id]
  
  example_qsip_filtered <- example_qsip[!asv_id %in% c(arch, mito_chloro, euk, unassign)]
  
  # Relativize sequence abundances
  example_qsip_filtered[, rel_abund := seq_abund / sum(seq_abund), by = sampleID]
  
  # Calculate WADs first
  wads <- calc_wad(example_qsip_filtered,
                   tax_id = 'asv_id', sample_id = 'sampleID', frac_id = 'fraction',
                   frac_dens = 'Density.g.ml', frac_abund = 'avg_16S_g_soil',
                   rel_abund = 'rel_abund',
                   grouping_cols = c('treatment', 'isotope', 'iso_trt', 'Phylum'))
  
  # Test calc_excess with bootstrapping (using fewer iterations for speed)
  eaf_boot <- calc_excess(wads, tax_id = 'asv_id', sample_id = 'sampleID',
                          iso_trt = 'iso_trt', isotope = 'isotope',
                          bootstrap = TRUE, iters = 99,
                          grouping_cols = c('treatment', 'isotope', 'iso_trt', 'Phylum'))
  
  # Tests..................................................
  
  # Basic structure tests
  expect_s3_class(eaf_boot, "data.table")
  expect_true(nrow(eaf_boot) > 0)
  
  # Check for bootstrap-specific columns
  bootstrap_cols <- c("2.5%", "50%", "97.5%", "p_val")
  expect_true(all(bootstrap_cols %in% names(eaf_boot)))
  
  # Check that bootstrap columns are numeric
  expect_true(is.numeric(eaf_boot$`2.5%`))
  expect_true(is.numeric(eaf_boot$`50%`))
  expect_true(is.numeric(eaf_boot$`97.5%`))
  expect_true(is.numeric(eaf_boot$p_val))
  
  # Check that confidence intervals make sense (2.5% <= 50% <= 97.5%)
  expect_true(all(eaf_boot$`2.5%` <= eaf_boot$`50%`, na.rm = TRUE))
  expect_true(all(eaf_boot$`50%` <= eaf_boot$`97.5%`, na.rm = TRUE))
  
  # Check that p_val is between 0 and 1
  expect_true(all(eaf_boot$p_val >= 0 & eaf_boot$p_val <= 1, na.rm = TRUE))
  
  # Check that we have expected grouping columns
  expected_cols <- c('asv_id', 'treatment', 'isotope', 'iso_trt', 'Phylum')
  expect_true(all(expected_cols %in% names(eaf_boot)))
})

