test_that("calc_excess throws appropriate errors for missing parameters", {
  data(example_qsip)
  
  # Prepare minimal dataset
  example_qsip[, rel_abund := seq_abund / sum(seq_abund), by = sampleID]
  wads <- calc_wad(example_qsip,
                   tax_id = 'asv_id', sample_id = 'sampleID', frac_id = 'fraction',
                   frac_dens = 'Density.g.ml', frac_abund = 'avg_16S_g_soil',
                   rel_abund = 'rel_abund')
  
# Tests..................................................

  # Test missing tax_id
  expect_error(calc_excess(wads, sample_id = 'sampleID', iso_trt = 'iso_trt', isotope = 'isotope'))
  
  # Test missing sample_id
  expect_error(calc_excess(wads, tax_id = 'asv_id', iso_trt = 'iso_trt', isotope = 'isotope'))
  
  # Test missing iso_trt
  expect_error(calc_excess(wads, tax_id = 'asv_id', sample_id = 'sampleID', isotope = 'isotope'))
  
  # Test missing isotope
  expect_error(calc_excess(wads, tax_id = 'asv_id', sample_id = 'sampleID', iso_trt = 'iso_trt'))
})